INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0000', NULL, 'pg_aesrg_000', 'paragraph', '{"text": "The note is a 5/1 ARM originated 2021-07-01 at 4.125% with a first adjustment on 2026-07-01. Margin is 2.75% over the index named in the note rider. Caps are 2.00% initial, 2.00% subsequent, 5.00% lifetime."}', 0, 0, 0, '2025-11-18T09:00:00Z', '2026-05-22T09:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0001', NULL, 'pg_aesrg_000', 'bulleted_list_item', '{"text": "Fully indexed rate = index + margin, then the cap test. The initial cap means the first adjusted rate cannot exceed 6.125% regardless of where the index sits."}', 0, 0, 1, '2025-11-18T10:00:00Z', '2026-05-22T10:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0002', NULL, 'pg_aesrg_000', 'bulleted_list_item', '{"text": "Freddie Mac PMMS showed 30-year FRM 6.52% and 15-year FRM 5.84% on 2026-06-11. That is market context for comparison, not the rate this loan will reset to."}', 0, 0, 2, '2025-11-18T11:00:00Z', '2026-05-22T11:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0003', NULL, 'pg_aesrg_000', 'bulleted_list_item', '{"text": "Open question for the servicer: exact rate-set date and which index publication date is used."}', 0, 0, 3, '2025-11-18T12:00:00Z', '2026-05-22T12:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0004', NULL, 'pg_aesrg_100', 'paragraph', '{"text": "Rejected the HELOC pitch and recorded why so it does not resurface.", "checked": false}', 0, 0, 0, '2025-11-18T21:10:00Z', '2026-05-22T21:40:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0005', NULL, 'pg_aesrg_100', 'to_do', '{"text": "Rejected the forum claim and recorded why so it does not resurface.", "checked": false}', 0, 0, 1, '2025-11-18T21:11:00Z', '2026-05-22T21:41:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0006', NULL, 'pg_aesrg_001', 'paragraph', '{"text": "Required escrow balance rose because the county reassessed the parcel after the roof permit finaled and the hazard carrier repriced for wildfire zone."}', 0, 0, 0, '2026-02-17T09:00:00Z', '2026-05-31T09:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0007', NULL, 'pg_aesrg_001', 'paragraph', '{"text": "Shortage may be paid in full or spread over 12 months. The spread raises the monthly escrow portion from $500.00 to roughly $653.50."}', 0, 0, 1, '2026-02-17T10:00:00Z', '2026-05-31T10:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0008', NULL, 'pg_aesrg_001', 'bulleted_list_item', '{"text": "Cash-flow decision: the spread is the lower monthly hit but costs more attention; the lump sum clears it. Neither option touches the Home Reserve Bucket."}', 0, 0, 2, '2026-02-17T11:00:00Z', '2026-05-31T11:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0009', NULL, 'pg_aesrg_001', 'paragraph', '{"text": "Verify the disbursement schedule the servicer used - if it assumes the pre-mitigation premium, the projection is too high."}', 0, 0, 3, '2026-02-17T12:00:00Z', '2026-05-31T12:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0010', NULL, 'pg_aesrg_101', 'to_do', '{"text": "Next step assigned to Daniel; due after the next payroll deposit. Left unresolved on purpose until the reset notice arrives.", "checked": true}', 0, 0, 0, '2026-02-17T21:10:00Z', '2026-05-31T21:40:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0011', NULL, 'pg_aesrg_101', 'paragraph', '{"text": "Filed the paperwork on 2026-06-09.", "checked": true}', 0, 0, 1, '2026-02-17T21:11:00Z', '2026-05-31T21:41:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0012', NULL, 'pg_aesrg_101', 'to_do', '{"text": "Filed the paperwork on 2026-06-13. Revisit after the written confirmation lands.", "checked": true}', 0, 0, 2, '2026-02-17T21:12:00Z', '2026-05-31T21:42:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0013', NULL, 'pg_aesrg_002', 'paragraph', '{"text": "Coverage A moved to replacement cost, which is the main driver of the premium change alongside the wildfire-zone rerating."}', 0, 0, 0, '2026-02-04T09:00:00Z', '2026-05-29T09:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0014', NULL, 'pg_aesrg_002', 'paragraph', '{"text": "Mitigation credit is available for Class A roof covering and defensible space; ember-resistant vents would add more."}', 0, 0, 1, '2026-02-04T10:00:00Z', '2026-05-29T10:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0015', NULL, 'pg_aesrg_002', 'paragraph', '{"text": "Because premiums are escrowed, a credit applied before the next analysis reduces the projected disbursement and therefore the shortage."}', 0, 0, 2, '2026-02-04T11:00:00Z', '2026-05-29T11:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0016', NULL, 'pg_aesrg_102', 'to_do', '{"text": "Rejected the skip-a-payment offer and recorded why so it does not resurface. Superseded an earlier note that assumed the old premium.", "checked": true}', 0, 0, 0, '2026-02-04T21:10:00Z', '2026-05-29T21:40:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0017', NULL, 'pg_aesrg_102', 'paragraph', '{"text": "Rejected the skip-a-payment offer and recorded why so it does not resurface. Attached the statement page to the escrow file.", "checked": true}', 0, 0, 1, '2026-02-04T21:11:00Z', '2026-05-29T21:41:00Z');
