INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0026', NULL, 'pg_aesrg_004', 'paragraph', '{"text": "The card balance is mostly the roof deductible and materials. Purchase APR is 23.75%."}', 0, 0, 0, '2026-04-03T09:00:00Z', '2026-05-23T09:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0027', NULL, 'pg_aesrg_004', 'paragraph', '{"text": "CFPB guidance: paying only the minimum can take years and cost substantially more in interest; paying above the minimum reduces total interest."}', 0, 0, 1, '2026-04-03T10:00:00Z', '2026-05-23T10:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0028', NULL, 'pg_aesrg_004', 'paragraph', '{"text": "Balance-transfer offers carry a transfer fee and suspend the grace period on new purchases. Read the go-to APR before moving anything."}', 0, 0, 2, '2026-04-03T11:00:00Z', '2026-05-23T11:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0029', NULL, 'pg_aesrg_104', 'to_do', '{"text": "Rejected the HELOC pitch and recorded why so it does not resurface. No change to the reserve floor either way.", "checked": false}', 0, 0, 0, '2026-04-03T21:10:00Z', '2026-05-23T21:40:00Z');
