INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0031', NULL, 'pg_aesrg_104', 'to_do', '{"text": "Rejected the skip-a-payment offer and recorded why so it does not resurface. Left unresolved on purpose until the reset notice arrives.", "checked": false}', 0, 0, 2, '2026-04-03T21:12:00Z', '2026-05-23T21:42:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0032', NULL, 'pg_aesrg_005', 'paragraph', '{"text": "Advertised teaser rates assume discount points and a credit tier and are explicitly not a commitment to lend; APR exceeds the quoted rate."}', 0, 0, 0, '2026-03-03T09:00:00Z', '2026-06-06T09:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0033', NULL, 'pg_aesrg_005', 'paragraph', '{"text": "\"Skip a payment\" offers capitalize deferred interest into the new principal."}', 0, 0, 1, '2026-03-03T10:00:00Z', '2026-06-06T10:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0034', NULL, 'pg_aesrg_005', 'bulleted_list_item', '{"text": "A HELOC secured by the house is not the tool for a one-time escrow shortage."}', 0, 0, 2, '2026-03-03T11:00:00Z', '2026-06-06T11:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0035', NULL, 'pg_aesrg_005', 'paragraph', '{"text": "Forum claims that escrow shortages are negotiable are anecdotal; the amount follows the annual analysis and applicable law."}', 0, 0, 3, '2026-03-03T12:00:00Z', '2026-06-06T12:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0036', NULL, 'pg_aesrg_105', 'paragraph', '{"text": "Next step assigned to Daniel; due after the next payroll deposit. Cross-checked against the account balance before recording.", "checked": true}', 0, 0, 0, '2026-03-03T21:10:00Z', '2026-06-06T21:40:00Z');
