INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_aesrg_0041', NULL, 'pg_aesrg_006', 'paragraph', '{"text": "It is excluded from every option under consideration for the reset and the shortage."}', 0, 0, 1, '2026-03-06T10:00:00Z', '2026-06-10T10:30:00Z');
